// Injected fetch-based httpRequest shim (task-runner-safe)
const __helpers = this.helpers;
async function __httpRequest(opts) {
  const method = (opts.method || 'GET').toUpperCase();
  const url = opts.url;
  const headers = Object.assign({}, opts.headers || {});
  const cfg = {
    method,
    url,
    headers,
    json: opts.json !== false,
    returnFullResponse: true,
    timeout: opts.timeout || 30000,
  };
  if (opts.body !== undefined && opts.body !== null) {
    cfg.body = opts.body;
    if (typeof opts.body === 'object' && !headers['Content-Type'] && !headers['content-type']) {
      cfg.headers['Content-Type'] = 'application/json';
    }
  }
  let res;
  try {
    res = await __helpers.httpRequest(cfg);
  } catch (err) {
    const status = err.httpCode || err.statusCode || (err.response && err.response.status) || 0;
    const body = (err.response && err.response.body) || err.body || null;
    const wrapped = new Error('HTTP ' + (status || 'network') + ': ' + (err.message || String(err)).slice(0, 300));
    wrapped.httpCode = status;
    wrapped.body = body;
    throw wrapped;
  }
  const status = res.statusCode || res.status || 0;
  const body = res.body !== undefined ? res.body : res;
  if (status < 200 || status >= 300) {
    const e = new Error('HTTP ' + status + ': ' + String(body).slice(0, 300));
    e.httpCode = status;
    e.body = body;
    throw e;
  }
  return body;
}


const fetch = async (url, options = {}) => {
  const opts = {
    method: options.method || 'GET',
    url: url,
    headers: options.headers || {},
    json: true,
    ignoreHttpStatusErrors: true
  };
  if (options.body) {
    opts.body = typeof options.body === 'string' ? JSON.parse(options.body) : options.body;
  }
  const res = await __httpRequest(opts);
  return {
    json: async () => res,
    ok: true,
    status: 200
  };
};

// Fetch workflow_runs for current month, group by agent and API
const now = new Date();
const monthStart = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();

const headers = {
  'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
  'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
  'Content-Type': 'application/json'
};

const spendResp = await fetch('https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/workflow_runs?created_at=gte.' + monthStart + '&order=created_at.desc&limit=2000', {
  headers
});
const runs = await spendResp.json();

const allRuns = Array.isArray(runs) ? runs : [];

// Group by agent
const byAgent = {};
for (const run of allRuns) {
  const agent = run.agent_id || 'unknown';
  if (!byAgent[agent]) {
    byAgent[agent] = { totalCost: 0, totalApiCalls: 0, runs: 0, outcomes: {}, totalOutcomeCount: 0 };
  }
  byAgent[agent].totalCost += (run.cost_usd || 0);
  byAgent[agent].totalApiCalls += (run.api_calls || 0);
  byAgent[agent].runs++;
  byAgent[agent].totalOutcomeCount += (run.outcome_count || 0);

  const outcome = run.outcome || 'unknown';
  if (!byAgent[agent].outcomes[outcome]) byAgent[agent].outcomes[outcome] = 0;
  byAgent[agent].outcomes[outcome]++;
}

return [{ json: { byAgent, totalRuns: allRuns.length, monthStart } }];

