const headers = {
  'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
  'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
  'Content-Type': 'application/json'
};

const capsResp = await fetch('https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/agent_capabilities?select=*&limit=500', {
  headers
});
const capabilities = await capsResp.json();

const prevData = $input.first().json;

return [{ json: { ...prevData, capabilities: Array.isArray(capabilities) ? capabilities : [] } }];

const data = $input.first().json;
const byAgent = data.byAgent || {};
const capabilities = data.capabilities || [];

const insights = [];
const recommendations = [];

// Build budget map from capabilities
const budgetMap = {};
const capsByAgent = {};
for (const cap of capabilities) {
  const agentId = cap.agent_id || cap.agent_name;
  if (!budgetMap[agentId]) {
    budgetMap[agentId] = cap.monthly_budget_usd || 0;
  } else {
    budgetMap[agentId] = Math.max(budgetMap[agentId], cap.monthly_budget_usd || 0);
  }
  if (!capsByAgent[agentId]) capsByAgent[agentId] = [];
  capsByAgent[agentId].push(cap);
}

// 1. Agents approaching budget limits (>80% used)
for (const [agent, info] of Object.entries(byAgent)) {
  const budget = budgetMap[agent] || 0;
  if (budget > 0) {
    const pct = (info.totalCost / budget) * 100;
    if (pct > 80) {
      insights.push({
        type: 'budget_warning',
        agent,
        detail: agent + ' has used $' + info.totalCost.toFixed(2) + ' of $' + budget.toFixed(2) + ' budget (' + pct.toFixed(1) + '%)',
        severity: pct > 100 ? 'critical' : 'warning'
      });
    }
  }
}

// 2. Cost per outcome metrics
for (const [agent, info] of Object.entries(byAgent)) {
  if (info.totalOutcomeCount > 0 && info.totalCost > 0) {
    const costPerOutcome = info.totalCost / info.totalOutcomeCount;
    insights.push({
      type: 'cost_per_outcome',
      agent,
      detail: agent + ': $' + costPerOutcome.toFixed(4) + ' per outcome (' + info.totalOutcomeCount + ' outcomes, $' + info.totalCost.toFixed(2) + ' total)',
      severity: 'info'
    });
  }
}

// 3. Free tier / unused capacity
for (const cap of capabilities) {
  const agentId = cap.agent_id || cap.agent_name;
  if (cap.is_active && (cap.monthly_spend_usd || 0) === 0 && (cap.monthly_budget_usd || 0) > 0) {
    recommendations.push({
      type: 'free_capacity',
      agent: agentId,
      api: cap.api_name || cap.capability_name || '',
      detail: 'Budget allocated but zero spend - free capacity available'
    });
  }
}

// 4. Model tiering suggestions
for (const [agent, info] of Object.entries(byAgent)) {
  if (info.totalCost > 5) {
    recommendations.push({
      type: 'model_tiering',
      agent,
      detail: 'Consider using Haiku for simple tasks, Sonnet for moderate tasks, and Opus only for complex reasoning to reduce costs'
    });
  }
}

return [{ json: { insights, recommendations, byAgent, totalRuns: data.totalRuns, capabilities } }];

