const data = $input.first().json;
const byAgent = data.byAgent || {};
const capabilities = data.capabilities || [];

const headers = {
  'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
  'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
  'Content-Type': 'application/json',
  'Prefer': 'return=representation'
};

// Update monthly_spend_usd for each agent's capabilities
for (const cap of capabilities) {
  const agentId = cap.agent_id || cap.agent_name;
  const agentData = byAgent[agentId];
  if (agentData && cap.id) {
    const spend = agentData.totalCost || 0;
    await fetch('https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/agent_capabilities?id=eq.' + cap.id, {
      method: 'PATCH',
      headers,
      body: JSON.stringify({ monthly_spend_usd: spend })
    });
  }
}

return [{ json: { ...data, capabilities_updated: true } }];

const data = $input.first().json;
const insights = data.insights || [];
const recommendations = data.recommendations || [];
const byAgent = data.byAgent || {};

const lines = [
  '--- MindMaker Cost Advisor - Weekly Report ---',
  '',
  'Agent: Marcus',
  'Total workflow runs this month: ' + (data.totalRuns || 0),
  ''
];

// Spend by agent
lines.push('-- Spend by Agent --');
for (const [agent, info] of Object.entries(byAgent)) {
  lines.push('  ' + agent + ': $' + (info.totalCost || 0).toFixed(2) + ' (' + info.runs + ' runs, ' + info.totalApiCalls + ' API calls)');
}
lines.push('');

// Insights
if (insights.length > 0) {
  lines.push('-- Insights --');
  for (const i of insights) {
    lines.push('  [' + i.severity.toUpperCase() + '] ' + i.detail);
  }
  lines.push('');
}

// Recommendations
if (recommendations.length > 0) {
  lines.push('-- Recommendations --');
  for (const r of recommendations) {
    lines.push('  - ' + r.detail);
  }
}

if (insights.length === 0 && recommendations.length === 0) {
  lines.push('All agents operating within budget. No issues detected.');
}

const message = lines.join('\n');

return [{ json: { message, insightCount: insights.length, recommendationCount: recommendations.length } }];
